import math

def three_sums(f, a, b, n):
    dx = (b - a) / n
    L = sum(f(a + i*dx) for i in range(n)) * dx
    R = sum(f(a + i*dx) for i in range(1, n + 1)) * dx
    M = sum(f(a + (i - 0.5)*dx) for i in range(1, n + 1)) * dx
    print(f"L = {L:.6f}, R = {R:.6f}, M = {M:.6f}")

k = int(input())
for i in range(k):
    # input().split() cuts a line at its spaces into a list of words
    words = input().split()
    if words[0] == "line":
        m, c = float(words[1]), float(words[2])
        f = lambda x: m*x + c
        words = words[2:]
    elif words[0] == "square":
        f = lambda x: x**2
    elif words[0] == "cube":
        f = lambda x: x**3
    elif words[0] == "sin":
        f = lambda x: math.sin(x)
    else:
        f = lambda x: 1 / x
    a = float(words[1])
    if words[2] == "pi":
        b = math.pi
    else:
        b = float(words[2])
    three_sums(f, a, b, int(words[3]))
